<section class="form-card" aria-labelledby="system-settings-title"><p class="eyebrow">Administration</p><h1 id="system-settings-title">System settings</h1><p>Keep essential behavior simple and explicit.</p><form method="post" action="<?= h(app_url('admin.settings.save')) ?>" class="stack" data-submit-feedback><?= csrf_field() ?><div class="form-field"><label for="site-name">Site name</label><input id="site-name" name="site_name" maxlength="80" value="<?= h($settings['site_name']??APP_NAME) ?>" required></div><div class="form-field"><label class="check-row"><input type="checkbox" name="maintenance_mode" value="1"<?= ($settings['maintenance_mode']??'0')==='1'?' checked':'' ?>><span>Enable maintenance mode</span></label><span class="field-hint">Blocks public, student, and vendor pages with a maintenance notice. Administrators can continue working; sign-in remains available.</span></div><div class="cash-note"><strong>Payment method: CASH ONLY</strong><br>Online payments are not configured or accepted by CampusBite.</div><button class="button" type="submit" data-loading-text="Saving…">Save settings</button></form></section>
